"""V5 лист FIN, G24: сборка `HARJ_HYBRID_V5_FINAL.md` и `REPRODUCTION_V5.md` из таблиц на диске. Дат и времени в документе нет (сборка дважды даёт тот же текст). Утверждения текста, зависящие от данных, проверяются `claims_fail`: не выполнены — сборка отказывает."""
from __future__ import annotations

from models_v2.s12 import v5_0_io as IO, v5_fin_data as D, v5_fin_doc as W, v5_fin_doc2 as W2, v5_fin_text as TX
from models_v2.s12.v5_fin_doc import f, hdr, s

FINAL = IO.ROOT / "docs/otchety/HARJ_HYBRID_V5_FINAL.md"
REPRO = IO.REP / "REPRODUCTION_V5.md"
STAGES = [("0", "run_v5"), ("DX1", "run_v5_dx"), ("GS", "run_v5"), ("SP", "run_v5"), ("FIN", "run_v5")]


def enc(t: dict, best: str, base: str, w: str):
    d = t["enc"]
    return d[(d["best"] == best) & (d["base"] == base) & (d["window"] == w)].iloc[0]


def claims_fail(t: dict) -> list:
    """Условия, на которых стоят словесные выводы документа."""
    a, y, bad = W.m(t), t["years"].set_index(["series", "year"])["qlike_m16"], []
    g1, s1 = t["gs"], t["sp"]
    ok = {"0 go": W.n_go(t) == 0, "SP1 лучше K8 в 2018": y[(s1, 2018)] < y[("K8", 2018)], "SP1 хуже K8 в каждом году с 2019": all(y[(s1, k)] > y[("K8", k)] for k in range(2019, 2027)),
          "GS4 лучше K8 в 2022, хуже в 2023–2025": a.loc[(g1, "2022"), "d_qlike_K8_pct_of_k1"] < 0 < a.loc[(g1, "2023_2025"), "d_qlike_K8_pct_of_k1"],
          "интервалы охвата SP1 к K8 включают 0 во всех окнах": all(enc(t, s1, "K8", w).w_lo90 <= 0 <= enc(t, s1, "K8", w).w_hi90 for w in ("2017_2021", "2022_2025", "all")),
          "интервал охвата GS4 к K8 в 2022–2025 включает 0": enc(t, g1, "K8", "2022_2025").w_lo90 <= 0 <= enc(t, g1, "K8", "2022_2025").w_hi90,
          "интервалы охвата GS4 к K8 в 2017–2021 и вся не включают 0": all(enc(t, g1, "K8", w).w_lo90 > 0 for w in ("2017_2021", "all")),
          "GS4 к M: интервал 2022–2025 выше 0": enc(t, g1, "M", "2022_2025").w_lo90 > 0}
    ab = t["abl"][t["abl"]["section"] == "qlike"].set_index(["chain", "window"])
    ok["SP4 − SP2 не значимо, SP2 хуже H3"] = ab.loc[("SP2→SP4", "all"), "dm_p"] > 0.05 and ab.loc[("H3→SP2", "all"), "delta_mean"] > 0
    ok["лучшие GS и SP значимо не лучше K8 по DM (основное семейство)"] = bool((t["tests"].query("kind == 'main' and comparator == 'K8' and delta_mean < 0")["dm_p"] > 0.05).all())
    return [k for k, v in ok.items() if not v]


def closure_block(t: dict) -> str:
    g, c, y = W.go_row(t), W2.closure(t), t["years"].set_index(["series", "year"])["qlike_m16"]
    b1, b2 = t["gs"], t["sp"]
    r = ["| 1 Graph-Score | stop: ни одна GS не проходит три условия; лучшая %s: crit_panel %s > %s, без 2017 %s > %s, без 1 %% %s > %s; выигрыш к K8 держится на 2022 |" % (b1, f(g.loc[b1, "crit_panel"]), f(g.loc[b1, "thr1"]), f(g.loc[b1, "crit_no2017"]), f(g.loc[b1, "thr2"]), f(g.loc[b1, "crit_trim1"]), f(g.loc[b1, "thr3"])),
         "| 2 Spectral | stop: лучшая %s проходит условия 1 и 2 (%s ≤ %s; %s ≤ %s), но не 3 (%s > %s); выигрыш — один год: 2018 QLIKE %s против K8 %s, с 2019 хуже K8 в каждом году |" % (b2, f(g.loc[b2, "crit_panel"]), f(g.loc[b2, "thr1"]), f(g.loc[b2, "crit_no2017"]), f(g.loc[b2, "thr2"]), f(g.loc[b2, "crit_trim1"]), f(g.loc[b2, "thr3"]), f(y[(b2, 2018)], 4), f(y[("K8", 2018)], 4)),
         "| 3 Moments | ABANDON: p Вальда K8 2017–2021 = %s > 0,01 — новой информации нет |" % f(c["p_wald"], 3),
         "| 4 Latent | ABANDON: структура совпадает с проверенными GS3, GS4, GS5 (скрытые факторы по прошлым score) |",
         "| 5 Jump | ABANDON: значимые скачки BNS в %s %% дней несут %s %% QLIKE K8 (нужно не менее чем вдвое больше доли дней); правило «J > 0» не выделяет дни: оно истинно в большинстве |" % (f(100 * c["share_rows"], 2), f(100 * c["share_qlike"], 2)),
         "| 6 Break | ABANDON: нет «go» направления 1 (план п. 3.6) |", "| 7 сочетания | ABANDON: нет «go» ни одного направления |"]
    return hdr(["направление", "решение, правило и число"]) + "\n".join(r) + "\n"


def special(t: dict) -> str:
    g1, s1 = t["gs"], t["sp"]
    e = lambda b, base, w: enc(t, b, base, w)
    iv = lambda r: "%s [%s; %s]" % (s(r.w_hat, 2), s(r.w_lo90, 2), s(r.w_hi90, 2))
    j = t["joint"]
    jv = lambda sec, w, a, b: float(j[(j["section"] == sec) & (j["window"] == w) & (j["a"] == a) & (j["b"] == b)]["value"].iloc[0])
    out = float(j[(j["section"] == "rv_outside_range") & (j["window"] == "2022_2025")]["value"].iloc[0])
    ab = t["abl"][t["abl"]["section"] == "qlike"].set_index(["chain", "window"])
    xt = float(j[(j["section"] == "cross_ticker_corr") & (j["window"] == "all") & (j["a"] == "K8")]["value"].iloc[0])
    return ("**Вопрос блока владельца:** действительно ли новые архитектуры извлекают информацию, которой нет в самостоятельных бустингах, или только заново воспроизводят уже известную RV?\n\n"
            "**Ответ.** Устойчивая информация сверх K8 (в ней уже есть HAR-J и бустинги) не показана ни у одной из девяти конфигураций; прогнозы новых архитектур практически повторяют K8 и бустинги. Показано следующее.\n\n"
            "1. **Охват** (QLIKE-оптимальный ex post вес w в K8^(1−w)·F^w; 90 %% интервал блоковым бутстрапом дат). В подтверждающем окне 2022–2025 у %s w = %s, у %s w = %s — оба интервала включают 0, веса сверх K8 нет; у SP1 интервал включает 0 во всех окнах. "
            "У %s в окне выбора 2017–2021 w = %s и за всю историю w = %s — интервалы не включают 0, но это окно выбора и история, в которой выигрыш к K8 держится на 2022 (в 2023–2025 GS4 хуже K8), значимых различий QLIKE нет (раздел 10). "
            "Относительно M = √(K2·K3) у %s в 2022–2025 w = %s (интервал не включает 0), но M не содержит HAR-J, а K8 = √(H·M) его содержит: это согласуется с тем, что %s несёт долю HAR-J (известную из V4), и не доказывает новой информации. Остальные окна и интервалы — таблица в разделе 15.\n"
            "2. **Совместные ошибки.** Корреляция ln(RV/F) %s с K8 — %s, %s с K8 — %s (вся история); ошибка одного знака с K8 в %s и %s долей дней. В 2022–2025 в %s долей дней RV лежит вне диапазона [min, max] шести прогнозов (K1, K2, K3, K8, %s, %s): ошибаются все в одну сторону. Новые архитектуры не дают независимой ошибки.\n"
            "3. **Абляция спектра.** %s − %s: Δ QLIKE (вся история) %s, p DM = %s (форма дня сверх спектра ничего не добавляет); %s хуже H3 (форма дня без спектра): Δ %s, p %s. Спектр сверх формы дня информации не несёт.\n\n"
            "**Не показано.** Отсутствие значимости не доказывает отсутствия информации: интервалы охвата широки (ширина w в 2022–2025: %s у %s и %s у %s), ошибки бумаг коррелированы (средняя межбумажная корреляция ошибок %s у K8), поэтому эффективная выборка меньше числа строк; "
            "результат — один исторический проход по одним данным (честной второй половины нет), мощность малых эффектов невелика; не проверены другие механизмы, чем GS1–GS5 и SP1–SP4 (направления 3–7 закрыты без счёта конфигураций по объявленным правилам).\n"
            % (g1, iv(e(g1, "K8", "2022_2025")), s1, iv(e(s1, "K8", "2022_2025")), g1, iv(e(g1, "K8", "2017_2021")), iv(e(g1, "K8", "all")), g1, iv(e(g1, "M", "2022_2025")), g1, g1, f(jv("corr", "all", "K8", g1), 3), s1, f(jv("corr", "all", "K8", s1), 3), f(jv("same_sign", "all", "K8", g1), 3), f(jv("same_sign", "all", "K8", s1), 3),
               f(out, 3), g1, s1, "SP4", "SP2", s(ab.loc[("SP2→SP4", "all"), "delta_mean"], 5), f(ab.loc[("SP2→SP4", "all"), "dm_p"], 3), "SP2", s(ab.loc[("H3→SP2", "all"), "delta_mean"], 5), f(ab.loc[("H3→SP2", "all"), "dm_p"], 3),
               f(e(g1, "K8", "2022_2025").w_hi90 - e(g1, "K8", "2022_2025").w_lo90, 2), g1, f(e(s1, "K8", "2022_2025").w_hi90 - e(s1, "K8", "2022_2025").w_lo90, 2), s1, f(xt, 3)))
